/* One native button controller; no navigation and no queued slide animations. */
(()=>{document.querySelectorAll('[data-uniify-faq]').forEach(box=>{const buttons=[...box.querySelectorAll('.acc-btn')];function set(button,open){button.classList.toggle('active',open);button.setAttribute('aria-expanded',String(open));button.closest('.accordion').classList.toggle('active-block',open);const panel=document.getElementById(button.getAttribute('aria-controls'));panel.hidden=!open;panel.classList.toggle('current',open);panel.style.display=open?'block':'none';}buttons.forEach(button=>{set(button,button.classList.contains('active'));button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();const smoother=window.ScrollSmoother?.get(),top=button.getBoundingClientRect().top;const open=button.getAttribute('aria-expanded')!=='true';buttons.forEach(other=>set(other,other===button&&open));button.focus({preventScroll:true});window.ScrollTrigger?.refresh();const now=smoother?smoother.scrollTop():window.scrollY;const destination=Math.max(0,now+button.getBoundingClientRect().top-top);if(smoother)smoother.scrollTop(destination);else window.scrollTo({top:destination,behavior:'instant'});});});});})();
